### Константы дизайна

#### iOS (SwiftUI)
```swift
struct DesignConstants {
    // Размеры кнопок
    static let primaryButtonBaseSize: CGFloat = 200
    static let primaryButtonSize: CGFloat = primaryButtonBaseSize * 1.2 // +20%
    static let primaryButtonCornerRadius: CGFloat = 25

    // Цвета и градиенты
    static let primaryGradient = LinearGradient(
        colors: [
            Color(hex: "#9C27B0"), // Светло-фиолетовый
            Color(hex: "#673AB7")  // Темно-фиолетовый
        ],
        startPoint: .topLeading,
        endPoint: .bottomTrailing
    )

    // Тени
    static let primaryButtonShadow = Shadow(
        color: Color.black.opacity(0.3),
        radius: 8,
        x: 0,
        y: 4
    )

    // Типографика
    static let primaryButtonFont = Font.system(size: 24, weight: .bold)
}

extension Color {
    init(hex: String) {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: hex).scanHexInt64(&int)
        let a, r, g, b: UInt64
        switch hex.count {
        case 3: (a, r, g, b) = (255, (int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
        case 6: (a, r, g, b) = (255, int >> 16, int >> 8 & 0xFF, int & 0xFF)
        case 8: (a, r, g, b) = (int >> 24, int >> 16 & 0xFF, int >> 8 & 0xFF, int & 0xFF)
        default: (a, r, g, b) = (1, 1, 1, 0)
        }
        self.init(.sRGB, red: Double(r) / 255, green: Double(g) / 255, blue: Double(b) / 255, opacity: Double(a) / 255)
    }
}
```

#### Android (Jetpack Compose)
```kotlin
object DesignConstants {
    // Размеры кнопок
    const val PRIMARY_BUTTON_BASE_SIZE_DP = 200
    const val PRIMARY_BUTTON_SIZE_DP = (PRIMARY_BUTTON_BASE_SIZE_DP * 1.2).toInt() // +20%
    const val PRIMARY_BUTTON_CORNER_RADIUS_DP = 25

    // Цвета и градиенты
    val PRIMARY_GRADIENT = Brush.linearGradient(
        colors = listOf(
            Color(0xFF9C27B0), // Светло-фиолетовый
            Color(0xFF673AB7)  // Темно-фиолетовый
        ),
        start = Offset(0f, 0f),
        end = Offset(Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY)
    )

    // Тени
    const val PRIMARY_BUTTON_ELEVATION_DP = 8

    // Типографика
    val PRIMARY_BUTTON_TEXT_STYLE = TextStyle(
        fontSize = 24.sp,
        fontWeight = FontWeight.Bold,
        color = Color.White
    )
}
```

### Компонент основной кнопки

#### iOS (SwiftUI)
```swift
struct PrimaryButton: View {
    let title: String
    let action: () -> Void
    @State private var isPressed = false

    var body: some View {
        Button(action: action) {
            Text(title)
                .font(DesignConstants.primaryButtonFont)
                .foregroundColor(.white)
                .frame(
                    width: DesignConstants.primaryButtonSize,
                    height: DesignConstants.primaryButtonSize
                )
                .background(
                    RoundedRectangle(cornerRadius: DesignConstants.primaryButtonCornerRadius)
                        .fill(DesignConstants.primaryGradient)
                        .shadow(
                            color: DesignConstants.primaryButtonShadow.color,
                            radius: DesignConstants.primaryButtonShadow.radius,
                            x: DesignConstants.primaryButtonShadow.x,
                            y: DesignConstants.primaryButtonShadow.y
                        )
                )
                .scaleEffect(isPressed ? 0.95 : 1.0)
        }
        .buttonStyle(PlainButtonStyle())
        .onLongPressGesture(minimumDuration: 0, maximumDistance: .infinity, pressing: { pressing in
            withAnimation(.easeInOut(duration: 0.1)) {
                isPressed = pressing
            }
        }, perform: {})
    }
}
```

#### Android (Jetpack Compose)
```kotlin
@Composable
fun PrimaryButton(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    var isPressed by remember { mutableStateOf(false) }

    Button(
        onClick = onClick,
        modifier = modifier
            .size(DesignConstants.PRIMARY_BUTTON_SIZE_DP.dp)
            .scale(if (isPressed) 0.95f else 1f)
            .pointerInput(Unit) {
                detectTapGestures(
                    onPress = {
                        isPressed = true
                        tryAwaitRelease()
                        isPressed = false
                    }
                )
            },
        shape = RoundedCornerShape(DesignConstants.PRIMARY_BUTTON_CORNER_RADIUS_DP.dp),
        colors = ButtonDefaults.buttonColors(
            containerColor = Color.Transparent
        ),
        elevation = ButtonDefaults.buttonElevation(
            defaultElevation = DesignConstants.PRIMARY_BUTTON_ELEVATION_DP.dp
        ),
        contentPadding = PaddingValues(0.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    brush = DesignConstants.PRIMARY_GRADIENT,
                    shape = RoundedCornerShape(DesignConstants.PRIMARY_BUTTON_CORNER_RADIUS_DP.dp)
                ),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = text,
                style = DesignConstants.PRIMARY_BUTTON_TEXT_STYLE
            )
        }
    }
}
```
